command:
mysql -uroot -p"$(cat /root/.dbroot_pw)" -e "
CREATE DATABASE IF NOT EXISTS appdata;
USE appdata;
CREATE TABLE IF NOT EXISTS orders (
  id INT PRIMARY KEY AUTO_INCREMENT,
  customer VARCHAR(64),
  amount DECIMAL(10,2),
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;
INSERT INTO orders (customer, amount) VALUES ('alice', 100.00), ('bob', 250.50), ('carol', 75.25);
"
echo rc=$?

